const pipeline = (x) => x();

const importers = [
  async (path) => {
    if (!/^\.[\\/](?:apps[\\/]play-ground[\\/]src[\\/]app(?:[\\/](?!\.)(?:(?:(?!(?:^|[\\/])\.).)*?)[\\/]|[\\/]|$)(?!\.)(?=.)[^\\/]*?\.(mdx|stories\.(js|jsx|ts|tsx)))$/.exec(path)) {
      return;
    }
  
    const pathRemainder = path.substring(27);
    return import(
      /* webpackChunkName: "[request]" */
      /* webpackInclude: /(?!.*node_modules)(?:[\\/]apps[\\/]play-ground[\\/]src[\\/]app(?:[\\/](?!\.)(?:(?:(?!(?:^|[\\/])\.).)*?)[\\/]|[\\/]|$)(?!\.)(?=.)[^\\/]*?\.(mdx|stories\.(js|jsx|ts|tsx)))$/ */
      './apps/play-ground/src/app/' + pathRemainder
    );
  }
  ,
  async (path) => {
    if (!/^\.[\\/](?:apps[\\/]play-ground[\\/]src[\\/]stories(?:[\\/](?!\.)(?:(?:(?!(?:^|[\\/])\.).)*?)[\\/]|[\\/]|$)(?!\.)(?=.)[^\\/]*?\.(mdx|stories\.(js|jsx|ts|tsx)))$/.exec(path)) {
      return;
    }
  
    const pathRemainder = path.substring(31);
    return import(
      /* webpackChunkName: "[request]" */
      /* webpackInclude: /(?!.*node_modules)(?:[\\/]apps[\\/]play-ground[\\/]src[\\/]stories(?:[\\/](?!\.)(?:(?:(?!(?:^|[\\/])\.).)*?)[\\/]|[\\/]|$)(?!\.)(?=.)[^\\/]*?\.(mdx|stories\.(js|jsx|ts|tsx)))$/ */
      './apps/play-ground/src/stories/' + pathRemainder
    );
  }
  
];

export async function importFn(path) {
  for (let i = 0; i < importers.length; i++) {
    const moduleExports = await pipeline(() => importers[i](path));
    if (moduleExports) {
      return moduleExports;
    }
  }
}